### --Section A — SQL fundamentals (Q1–Q10)

 --`SELECT`, `WHERE`, `DISTINCT`, `ORDER BY`, `LIMIT`, `LIKE`, `BETWEEN`
--Q1. Retrieve all customer records.
select * from customers;

--Q2. Display customer names, cities, and segments.
select customer_name,city,customer_segment
from customers;

--Q3. Find customers living in Nairobi.
select * from customers c 
where city= 'Nairobi';

--Q4. Find customers registered after January 1, 2025.
select * from customers c
where registration_date > '2025-01-01'
limit 5;

--Q5. Display all unique customer cities.
select distinct city as distinct_Cities
from customers c;

--Q6. Retrieve the 10 most recent orders.
select product_name,order_date,order_id
from orders o
order by order_date desc
limit 5 ;


--Q7. Find orders with unit prices above KSh 10,000.
select order_id,product_name,product_category,unit_price
from orders o 
where unit_price >'10000';


--Q8. Find customers whose names start with A.
select * from customers
where customer_name like 'A%';

select customer_name
from customers;

--Q9. Retrieve orders with quantities between 2 and 5.
select * from orders  
where quantity between 2 and 5;

--Q10. Find orders paid through M-Pesa.
select * from orders;

select order_id,product_name,payment_method
from orders o 
where payment_method ='M-Pesa';


--### Section B — Aggregation and grouping (Q11–Q20)

*Concepts:* `COUNT`, `SUM`, `AVG`, `MIN`, `MAX`, `GROUP BY`, `HAVING`, `ROUND`

```sql
SELECT group_column, SUM(...) AS total
FROM table WHERE row_condition
GROUP BY group_column
HAVING SUM(...) > 1000;      -- HAVING filters groups; WHERE filters rows

select * from customers;
select * from orders;
--Q11. Count all customers.
select count(*) from customers

--Q12. Count all orders.
select count(*) from orders;

--Q13. Calculate completed-order revenue.
quantity * unit_price * (1 - discount / 100)

select sum(quantity*unit_price* (1-discount/100)) as completed_orders_revenue
from orders
where order_status ='completed';

SELECT COUNT(*) FROM orders WHERE order_status = 'completed';

--Q14. Calculate the average completed-order value.
select avg(quantity*unit_price* (1-discount/100)) as average_completed_order_revenue
from orders 
where order_status = 'Completed';

--Q15. Find the highest and lowest product prices.
select * from orders;
select max(unit_price) as max_product_price
from orders;

select min(unit_price) as min_product_price
from orders;

--Q16. Calculate revenue by product category.
select  product_category,sum(quantity*unit_price* (1-discount/100)) as total_produc_revenue
from orders
group by product_category;


--Q17. Count customers by city.
select  city,count(*)  as customer_citycount from customers
group by city;

--Q18. Calculate quantity sold by product.
select * from orders;
select sum(quantity) as quantity_sold_products,product_name
from orders
group by product_name 
order by sum(quantity) desc;

--Q19. Find categories generating more than KSh 100,000 in revenue.
select * from orders;

select product_category,sum(quantity*unit_price* (1-discount/100)) as product_total_revenue
from orders o 
where order_status ='Completed'
group by product_category
having sum(quantity*unit_price* (1-discount/100)) >100000
order by product_total_revenue;

20. Calculate the percentage of cancelled orders.

select * from orders;
select count(*) filter(where order_status ='Cancelled') * 100/count(*)
as cancelled_orders_poercentage
from orders;

--### Section C — Joins and customer analytics (Q21–Q28)
--*Concepts:* `INNER JOIN`, `LEFT JOIN`, `GROUP BY`, `HAVING`

--Q21. Display orders with customer names and cities.
select  * from orders;
select customer_name,o.customer_id,city,order_id,product_name
from orders o 
join customers c
on c.customer_id=o.customer_id;

--Q22. Calculate total spending by customer.
select * from customers;
select customer_name,c.customer_id,sum(quantity*unit_price*(1-discount/100)) as Total_spending_by_customer
from customers c
left join orders o
on c.customer_id=o.customer_id
where order_status='Completed'
group by c.customer_id 
order by Total_spending_by_customer desc;

--Q23. Identify customers who have never ordered.
select c.customer_id,c.customer_name,order_id
from customers c
left join orders o
on c.customer_id=o.customer_id
where order_status is null;

--Q24. Find the 10 highest-spending customers.
select customer_name,c.customer_id,coalesce(sum(quantity*unit_price*(1-discount/100)),0) as amount
from customers c
left join orders o
on c.customer_id=o.customer_id
group by customer_name,c.customer_id
order by amount desc
limit 10 ;

--Q25. Calculate revenue by customer city.
select city,sum(quantity*unit_price *(1-discount/100)) as revenue
from customers c
inner join orders o
on c.customer_id=o.customer_id
where order_status='Completed'
group by c.city
order by revenue desc;

select sum(quantity*unit_price*(1-discount/100))
from orders 
where order_status='Completed';

--Q26. Identify customers with more than five orders.
select c.customer_id,c.customer_name,count(o.order_id) as order_count
from customers c
join orders o 
on c.customer_id=o.customer_id 
group by c.customer_id,c.customer_name
having count(o.order_id)> 5;

--Q27. Calculate average customer spending by segment.
select * from orders;
select * from customers;

select c.customer_segment,round(avg(o.quantity*o.unit_price*(1-o.discount/100)), 2) as average_customer_spending
from customers c
join orders o
on c.customer_id=o.customer_id
where order_status ='Completed'
group by c.customer_segment
order by average_customer_spending;

--Q28. Identify the most popular category among VIP customers.
select product_category,count(distinct o.order_id) as orders_count,sum(order_id) as unit_sold
from orders o
join customers c
on c.customer_id=o.customer_id
where c.customer_segment ='VIP'
group by product_category
order by orders_count desc
limit 1 ;

--### Section D — Subqueries and CTEs (Q29–Q34)
--*Concepts:* subqueries, `WITH` (CTEs), nested aggregation

```sql
WITH step_one AS (
    SELECT customer_id, SUM(...) AS total FROM orders GROUP BY customer_id
)
SELECT * FROM step_one WHERE total > (SELECT AVG(total) FROM step_one);

--Q29. Find customers spending above the average total spending per purchasing customer.
with customer_spending as (select customer_id, sum(quantity*unit_price*(1-discount/100)) as total_customer_spending 
from orders 
where order_status ='Completed' 
group by customer_id)
select* from customer_spending 
where total_customer_spending > (select avg(total_customer_spending) from customer_spending)
order by total_customer_spending desc;

--Q30. Find products priced above the overall average unit price.
select distinct product_name, unit_price
from orders
where unit_price > (select avg(unit_price) from orders)
order by unit_price desc;

--Q31. Use a CTE to identify the three highest-revenue months.
with monthly_revenue as (
select date_trunc('month', order_date) as order_month,
sum(quantity * unit_price * (1 - discount / 100.0)) as revenue from orders
where order_status = 'Completed'
group by date_trunc('month', order_date))
select  order_month, round(revenue, 2) as revenue
from  monthly_revenue
order by revenue DESC
limit 3;


--Q32. Find customers purchasing from at least three categories.
select customer_id,count(distinct product_category) as category_count from orders o 
where order_status='Completed'
group by customer_id
having count(distinct product_category) >=3
order by category_count;
    
--Q33. Use a CTE to calculate category revenue, cost, profit, and profit margin.
with detailed_category as (
select product_category,sum(quantity*unit_price*(1-discount/100)) as revenue,sum(quantity*unit_price) as cost
from orders o 
where order_status ='Completed'
group by o.product_category )
select product_category,round(revenue, 2) as revenue,round(cost, 2) as cost, round(revenue-cost , 2) as profit,round((revenue - cost) * 100.0 /NULLIF(revenue, 0), 2) AS profit_margin_percentage
from detailed_category
order by profit desc;

--Q34. Find customers whose latest completed order is more than 90 days before the latest order date in the dataset.


--Q35. Rank customers by spending using `RANK()`.
select customer_id, sum(quantity*cost_price) as total_spent,
rank()over(order by sum(quantity*cost_price) desc) as customer_rank
from orders
group by customer_id; 
    
--Q36. Number each customer's orders by recency using `ROW_NUMBER()`.
select customer_id, order_date,
row_number()over(order by order_date desc) as recency
from orders o 
group by customer_id, order_date;
    
--Q37. Rank products within categories using `DENSE_RANK()`.
select product_name, product_category, sum(quantity*cost_price) as cost,
dense_rank() over(partition by product_category order by sum(quantity*cost_price) desc) as product_rank
from orders
group by product_name, product_category;

--Q38. Calculate cumulative monthly revenue.
select to_char(order_date, 'YYYY-MM') as month,
sum(quantity*unit_price*(1-discount/100)) over (partition by to_char(order_date, 'MM'))
from orders;

--Q39. Compare monthly revenue using `LAG()`.
with monthly_revenue as ( select  date_trunc('month', order_date)::date  as month,
sum(quantity * unit_price * (1 - discount / 100)) as revenue
from orders
where order_status = 'Completed'
group by date_trunc('month', order_date))
select  month,
round(revenue, 2) as revenue,
round(lag(revenue) over(order by month), 2) as previous_month_revenue,
round(revenue - lag(revenue) over (order by month), 2) as difference_ksh
from monthly_revenue
order by month;


--Q40. Calculate month-over-month revenue growth (%).
with monthly as (
select  DATE_TRUNC('month', order_date)::DATE AS month,
SUM(quantity * unit_price * (1 - discount / 100)) AS revenue
from orders
where order_status = 'Completed'
group by DATE_TRUNC('month', order_date))
select  month, ROUND(revenue, 2) as  revenue,ROUND(LAG(revenue) over (order by month), 2) as  previous_month_revenue,
ROUND((revenue - LAG(revenue) over (order by month))/ NULLIF(LAG(revenue) over (order by month), 0) * 100, 2) as month_over_month_growth_perecentage
from  monthly
order by month;

-- Q41: Divide customers into four spending groups using NTILE(4)
with customer_spending as (
select  c.customer_id,c.customer_name,c.customer_segment,SUM(o.quantity * o.unit_price * (1 - o.discount / 100)) as  total_spent
from customers c
join orders o
on o.customer_id = c.customer_id
where o.order_status = 'Completed'
group by c.customer_id, c.customer_name, c.customer_segment)
select customer_id,customer_name,customer_segment,ROUND(total_spent, 2) AS total_spent,
NTILE(4) over (order by total_spent DESC) as group_spending
from customer_spending
order by group_spending, total_spent DESC;


-- Q42: Calculate each category's share of total revenue using window functions.
select  product_category,ROUND(SUM(quantity * unit_price * (1 - discount / 100)), 2) as revenue_category,
ROUND(SUM(SUM(quantity * unit_price * (1 - discount / 100))) OVER (), 2) AS total_revenue,
ROUND(SUM(quantity * unit_price * (1 - discount / 100)) * 100/ SUM(SUM(quantity * unit_price * (1 - discount / 100))) over (), 2) as revenue_share_percentage
from orders
where order_status = 'Completed'
group by product_category
order by revenue_share_percentage DESC;




-- Section F — Advanced business intelligence 

-- Q43: Create a monthly_sales_summary view (month, orders, revenue, cost, profit)
create or replace view monthly_sales_summary AS
SELECT DATE_TRUNC('month', order_date)::DATE AS month,COUNT(*) AS total_orders,
COUNT(*) FILTER (WHERE order_status = 'Completed') AS completed_orders,
ROUND(COALESCE(SUM(quantity * unit_price * (1 - discount / 100)) FILTER (WHERE order_status = 'Completed'), 0), 2) AS revenue,
ROUND(COALESCE(SUM(quantity * cost_price) FILTER (WHERE order_status = 'Completed'), 0), 2) AS cost,
ROUND(COALESCE(SUM(quantity * unit_price * (1 - discount / 100) - quantity * cost_price) FILTER (WHERE order_status = 'Completed'), 0), 2) AS profit
from orders
group by DATE_TRUNC('month', order_date);
SELECT * FROM monthly_sales_summary ORDER BY month;


-- Q44: Function returning completed-order revenue for a given customer ID
create or replace function customer_revenue(p_customer_id INTEGER)
returns NUMERIC
language plpgsql
as $$
declare v_revenue NUMERIC;
begin
select  COALESCE(SUM(quantity * unit_price * (1 - discount / 100)), 0)
into v_revenue
from  orders
where customer_id = p_customer_id
and  order_status = 'Completed';
return ROUND(v_revenue, 2);
end;
$$;
select  customer_revenue(1)    AS revenue_customer_1;     
select customer_revenue(9999) AS revenue_missing_id;     


-- Q45: Segment customers into High, Medium and Low Value
with customer_spend as (
select customer_id,SUM(quantity * unit_price * (1 - discount / 100)) AS total_spent
from orders
where order_status = 'Completed'
group by customer_id
)
select ROUND(MIN(total_spent), 2) AS minimum_spent,
       ROUND(PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY total_spent)::NUMERIC, 2) AS p25,
       ROUND(PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY total_spent)::NUMERIC, 2) AS median,
       ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY total_spent)::NUMERIC, 2) AS p75,
       ROUND(MAX(total_spent), 2) AS maximum_spent
from customer_spend;

with customer_spend as (
select c.customer_id,c.customer_name,c.customer_segment,COALESCE(SUM(o.quantity * o.unit_price * (1 - o.discount / 100)), 0) AS total_spent,
COUNT(o.order_id) AS completed_orders
from customers c
left join orders o
on o.customer_id = c.customer_id
and o.order_status = 'Completed'     
group by c.customer_id, c.customer_name, c.customer_segment
),
thresholds AS (
select  PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY total_spent) AS p25,
PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY total_spent) AS p75
from customer_spend
where completed_orders > 0
)
select cs.customer_id,cs.customer_name, cs.customer_segment,ROUND(cs.total_spent, 2) AS total_spent,
case
when cs.completed_orders = 0 THEN 'No Purchases'
when cs.total_spent >= t.p75 THEN 'High Value'
when cs.total_spent >= t.p25 THEN 'Medium Value'
else 'Low Value'
end as value_band
from customer_spend cs
cross join  thresholds t
order by  cs.total_spent DESC;


-- Q46: Management report
-- (a) Top five customers by completed revenue
select  c.customer_id,c.customer_name,c.city, c.customer_segment,
ROUND(SUM(o.quantity * o.unit_price * (1 - o.discount / 100)), 2) AS revenue
from customers c
join orders o on o.customer_id = c.customer_id
where o.order_status = 'Completed'
group by c.customer_id, c.customer_name, c.city, c.customer_segment
order by revenue DESC
LIMIT 5;

-- (b) Top five products by completed revenue
select product_name,product_category,SUM(quantity) AS units_sold,
ROUND(SUM(quantity * unit_price * (1 - discount / 100)), 2) AS revenue
from orders
where  order_status = 'Completed'
group by product_name, product_category
order by revenue DESC
LIMIT 5;

-- (c) Most profitable category (by total profit, with margin shown)
select product_category,
ROUND(SUM(quantity * unit_price * (1 - discount / 100)), 2) AS revenue,
ROUND(SUM(quantity * unit_price * (1 - discount / 100) - quantity * cost_price), 2) AS profit,
ROUND(SUM(quantity * unit_price * (1 - discount / 100) - quantity * cost_price) * 100
/ NULLIF(SUM(quantity * unit_price * (1 - discount / 100)), 0), 2) AS profit_margin_percentage
from orders
where order_status = 'Completed'
group by  product_category
order by profit DESC
LIMIT 1;

-- (d) Lowest-revenue month 
select month, total_orders, revenue, profit
from monthly_sales_summary
order by revenue ASC
LIMIT 1;





















